import debim_ple_tools as d
import numpy as np

arr = d.read_png_rgba('input/A-101.png')
gray = np.mean(arr[:, :, :3], axis=2)
dark = gray < 100
cleaned = dark.copy()
for r in range(cleaned.shape[0]):
    row = cleaned[r]
    diff = np.diff(np.pad(row, (1, 1), 'constant'))
    starts = np.where(diff == 1)[0]
    ends = np.where(diff == -1)[0]
    for s, e in zip(starts, ends):
        if e - s >= 25:
            cleaned[r, s:e] = 0

for c in range(cleaned.shape[1]):
    col = cleaned[:, c]
    diff = np.diff(np.pad(col, (1, 1), 'constant'))
    starts = np.where(diff == 1)[0]
    ends = np.where(diff == -1)[0]
    for s, e in zip(starts, ends):
        if e - s >= 25:
            cleaned[s:e, c] = 0

dilated = cleaned.copy()
for dr in [-1, 0, 1]:
    for dc in [-2, -1, 0, 1, 2]:
        dilated |= np.roll(np.roll(cleaned, dr, axis=0), dc, axis=1)

H, W = dilated.shape
visited = np.zeros((H, W), dtype=bool)
clusters = []
for r in range(0, H, 2):
    for c in range(0, W, 2):
        if dilated[r, c] and not visited[r, c]:
            q = [(r, c)]
            visited[r, c] = True
            pts = []
            while q:
                cr, cc = q.pop()
                pts.append((cr, cc))
                for nr, nc in [(cr+2, cc), (cr-2, cc), (cr, cc+2), (cr, cc-2)]:
                    if 0 <= nr < H and 0 <= nc < W and dilated[nr, nc] and not visited[nr, nc]:
                        visited[nr, nc] = True
                        q.append((nr, nc))
            pts = np.array(pts)
            r1, c1 = pts.min(axis=0)
            r2, c2 = pts.max(axis=0)
            if len(pts) > 10 and (r2-r1) > 4:
                clusters.append((r1, c1, r2, c2))

print(f'Total text clusters: {len(clusters)}')
clusters.sort()
for idx, (r1, c1, r2, c2) in enumerate(clusters[:30]):
    print(f'Cluster {idx}: y=[{r1}..{r2}], x=[{c1}..{c2}], size={r2-r1}x{c2-c1}')
