import debim_ple_tools as d
import numpy as np

arr = d.read_png_rgba('input/A-301.png')
gray = np.mean(arr[:, :, :3], axis=2)

# In y: 285..305, there are several labels across x: 500..900
# Let us segment them along x
sub = (gray[285:305, 500:900] < 150).astype(int)
col_sum = np.sum(sub, axis=0)

# find non-empty regions along x
regions = []
in_r = False
s = 0
for c in range(len(col_sum)):
    if col_sum[c] > 0:
        if not in_r:
            s = c
            in_r = True
    else:
        if in_r:
            regions.append((s, c-1))
            in_r = False
if in_r: regions.append((s, len(col_sum)-1))

print(f'Found {len(regions)} regions:')
for idx, (sc, ec) in enumerate(regions):
    if ec - sc > 15:
        ch = sub[:, sc:ec+1]
        print(f'Region {idx} (x={500+sc}..{500+ec}):')
        for r in range(ch.shape[0]):
            row_str = ''.join('#' if ch[r, c] else ' ' for c in range(ch.shape[1]))
            if '#' in row_str:
                print(row_str)
