import debim_ple_tools, numpy as np

img = debim_ple_tools.read_png_rgba('input/A-101.png')
rgb = img[:, :, :3]
dark = np.mean(rgb, axis=2) < 100

# Subregion inside frame: Y in [80, 1020], X in [160, 1370]
sub = dark[80:1020, 160:1370]

# Look for lines spanning >= 100 px
h_lines = {}
for y in range(sub.shape[0]):
    row = sub[y, :]
    diff = np.diff(np.pad(row.astype(int), 1))
    starts = np.where(diff == 1)[0]
    ends = np.where(diff == -1)[0]
    for s, e in zip(starts, ends):
        if e - s >= 100:
            h_lines.setdefault(y + 80, []).append((s + 160, e + 160, e - s))

v_lines = {}
for x in range(sub.shape[1]):
    col = sub[:, x]
    diff = np.diff(np.pad(col.astype(int), 1))
    starts = np.where(diff == 1)[0]
    ends = np.where(diff == -1)[0]
    for s, e in zip(starts, ends):
        if e - s >= 100:
            v_lines.setdefault(x + 160, []).append((s + 80, e + 80, e - s))

print('Distinct Y of major horizontal lines:')
for y in sorted(h_lines.keys()):
    runs = h_lines[y]
    max_len = max(r[2] for r in runs)
    if max_len >= 300:
        print(f'  Y={y}: runs={runs}')

print('Distinct X of major vertical lines:')
for x in sorted(v_lines.keys()):
    runs = v_lines[x]
    max_len = max(r[2] for r in runs)
    if max_len >= 300:
        print(f'  X={x}: runs={runs}')
"
